extracted_python_code:
result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            (
                STARTSWITH(LOWER(name), 'j') | 
                ENDSWITH(LOWER(name), 'ez')
            ) & 
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

distinct_buying_customer_ids = Transactions.WHERE(transaction_type == 'buy').PARTITION(name="distinct_buyers", by=customer_id).CALCULATE(
    customer_id=customer_id
)

distinct_ticker_ids_on_or_after_date = Tickers.WHERE(
    HAS(historical_prices.WHERE(date >= "2023-04-01")) == 1
).CALCULATE(
    ticker_id=_id
)

num_transactions_recent_customers = Broker.CALCULATE(
    total_transactions_from_recent_joiners=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, 'now') <= 70
        ).transactions_made
    )
)

asp_q1_2023 = Dealership.CALCULATE(
    average_sale_price_q1_2023=AVG(
        Sales.WHERE(
            (YEAR(sale_date) == 2023) & 
            ISIN(MONTH(sale_date), (1, 2, 3))
        ).sale_price
    )
)

average_days_to_payment = Dealership.CALCULATE(
    avg_days_sale_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_difference=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_difference
        ),
        2
    )
)

result = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE((snapshot_date == sale_date) & (is_in_inventory == False))) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    car_make=car.make,
    car_model=car.model,
    sale_price=sale_price
)

total_sales_count_last_7_days = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 6))
)

salespersons_with_cash_payments = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == "cash")) == 1
).CALCULATE(salesperson_id=_id)

# Define the start and end dates for the 3-month period
start_period_date = DATETIME('now', '-3 months')
end_period_date = DATETIME('now')

# Find the top 3 salespersons by revenue in the last 3 months
top_sales_reps_by_revenue = Salespersons.WHERE(
    HAS(sales_made.WHERE(
        (sale_date >= start_period_date) & (sale_date <= end_period_date)
    )) == 1  # Ensure the salesperson has sales in the specified period
).CALCULATE(
    rep_first_name=first_name,
    rep_last_name=last_name,
    total_sales_num=COUNT(
        sales_made.WHERE(
            (sale_date >= start_period_date) & (sale_date <= end_period_date)
        )
    ),
    total_revenue_val=SUM(
        sales_made.WHERE(
            (sale_date >= start_period_date) & (sale_date <= end_period_date)
        ).sale_price
    )
).TOP_K(3, by=total_revenue_val.DESC())

weekend_payments_to_utility_company = Dealership.CALCULATE(
    num_weekend_payments=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == 'Utility Company') &
            (ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday')))
        )
    )
)

patients_with_gmail_or_yahoo = Patients.WHERE(
    ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
)
result = DermTreatment.CALCULATE(
    count_patients_gmail_yahoo=COUNT(patients_with_gmail_or_yahoo)
)

result = DermTreatment.CALCULATE(
    num_patients_matching_criteria=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (treatments_received.diagnosis.diag_name == 'Psoriasis vulgaris') &
                    (treatments_received.drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

alice_treatments_last_6_months_exclusive = DermTreatment.CALCULATE(
    num_treatments_for_alice = COUNT(
        Patients.WHERE(first_name == "Alice").treatments_received.WHERE(
            (start_dt >= DATETIME('now', 'start of month', '-6 months')) &
            (start_dt < DATETIME('now', 'start of month'))
        )
    )
)

result = DermTreatment.CALCULATE(
    avg_weight_drugalin_patients = AVG(
        Patients.WHERE(
            HAS(treatments_received.WHERE(drug.drug_name == 'Drugalin')) == 1
        ).weight_kg
    )
)

caw_for_male_patients = DermTreatment.CALCULATE(
    caw_male_patients=AVG(Patients.WHERE(gender == "Male").weight_kg)
)

pic_female_patients = DermTreatment.CALCULATE(
    private_insured_female_patient_count=COUNT(
        Patients.WHERE((gender == "Female") & (ins_type == "Private"))
    )
)

# Filter doctors who have prescribed biologic drugs
biologic_prescribing_doctors = Doctors.WHERE(
    HAS(prescribed_treatments.drug.WHERE(drug_type == 'biologic')) == 1
)

# Get the distinct states of these doctors
distinct_states_of_doctors = biologic_prescribing_doctors.PARTITION(
    name="states_group", by=(loc_state)
).CALCULATE(
    doctor_state=loc_state
)

average_age_male_private_insurance = DermTreatment.CALCULATE(
    avg_patient_age=AVG(
        Patients.WHERE(
            (gender == "Male") & (ins_type == "Private")
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age_in_years
    )
)

result = Ewallet.CALCULATE(
    tuc_count=COUNT(
        UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month'))
    )
)

top_merchants_by_amount = Merchants.WHERE(
    # Ensure the merchant has received transactions matching the criteria
    HAS(transactions_received.WHERE(
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150) &  # Transaction within the last 150 days
        (receiver_type == 1)  # Receiver is of type 1 (Merchant)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions_count=COUNT(transactions_received.WHERE(
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150) &
        (receiver_type == 1)
    )),
    total_transaction_amount=SUM(transactions_received.WHERE(
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150) &
        (receiver_type == 1)
    ).amount)
).TOP_K(
    2,  # Select top 2 merchants
    by=total_transaction_amount.DESC()  # Order by total transaction amount descending
)
